class IGOIconManager
{
public:
  class Icon
  {
    char prefix[108];

  public:
    float vy;

  private:
    char suffix[16];
  };

private:
  char prefix[2760];
  Icon* icons;
  char before_num_icons[140];
  int numIcons;
  int iconCounter;

public:
  void PopIcon(int icon);
};

void IGOIconManager::PopIcon(int icon)
{
  for(int i=icon; i<numIcons; i++)
  {
    if(i != numIcons-1)
      icons[i] = icons[i+1];
  }
  numIcons--;
  for(int i=icon; i<numIcons; i++)
    if(icons[i].vy == 0.0f)
      icons[i].vy = 0.01;

  iconCounter++;
}
